public class IsogramChecker {
    public static boolean isIsogram(String str) {
        if (str.isEmpty()) {
            return true;
        }
        str = str.toLowerCase();
        Set<Character> charSet = new HashSet<>();
        for (char c : str.toCharArray()) {
            if (charSet.contains(c)) {
                return false;
            }
            charSet.add(c);
        }
        return true;
    }
}

