public static String getMiddleCharacter(String word) {
        int length = word.length();
        int middle = length / 2;

        if (length % 2 == 0) {
            return word.substring(middle - 1, middle + 1);
        } else {
            return String.valueOf(word.charAt(middle));
        }
    }

public static double calculateExpression(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n debe ser mayor o igual a 1");
        }

        long factorialSum = 0;
        long factorial = 1;

        for (int i = 1; i <= n; i++) {
            factorial *= i;
            factorialSum += factorial;
        }

        return (double) factorialSum / nFactorial;
    }

public static int calculatePerimeter(String[] arr) {
        int rows = arr.length;
        int cols = arr[0].length();
        int perimeter = 0;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (arr[i].charAt(j) == 'X') {
                    if (i == 0 || arr[i - 1].charAt(j) == 'O') {
                        perimeter++;
                    }
                    if (i == rows - 1 || arr[i + 1].charAt(j) == 'O') {
                        perimeter++;
                    }
                    if (j == 0 || arr[i].charAt(j - 1) == 'O') {
                        perimeter++;
                    }
                    if (j == cols - 1 || arr[i].charAt(j + 1) == 'O') {
                        perimeter++;
                    }
                }
            }
        }

        return perimeter;
    }

