            // Verificar paréntesis balanceados
            boolean paréntesisBalanceados = true;
            Stack<Character> stack = new Stack<>();
            for (char c : expresion.toCharArray()) {
                if (c == '(') {
                    stack.push(c);
                } else if (c == ')') {
                    if (stack.isEmpty()) {
                        paréntesisBalanceados = false;
                        break;
                    }
                    stack.pop();
                }
            }
            if (!stack.isEmpty()) {
                paréntesisBalanceados = false;
            }


            boolean operadoresValidos = true;
