public static int[] findSmallestNumber(String numStr) {
        //String numStr = String.valueOf(n);
        int len = numStr.length();
        int[] result = {Integer.parseInt(numStr), 0, 0}; // Default result if no changes are needed

        for (int i = 0; i < len; i++) {
            for (int j = 0; j < len; j++) {
                if (i != j) {
                    String newNumStr = moveDigit(numStr, i, j);
                    int newNum = Integer.parseInt(newNumStr);
                    if (newNum < result[0]) {
                        result[0] = newNum;
                        result[1] = i;
                        result[2] = j;
                    }
                }
            }
        }
        return result;
    }

    public static String moveDigit(String numStr, int i, int j) {
        StringBuilder sb = new StringBuilder(numStr);
        char digit = sb.charAt(i);
        sb.deleteCharAt(i);
        sb.insert(j, digit);
        return sb.toString();
    }

function rearrangeToGrow(num) {
    if (typeof num !== 'number' || num < 0 || !Number.isInteger(num)) {
        throw new Error('Input must be a non-negative integer');
    }

    // Convert the number to a string, split it into an array of characters, sort in descending order, and join back to a string
    let sortedNumStr = num.toString().split('').sort((a, b) => b - a).join('');

    // Convert the sorted string back to a number
    return parseInt(sortedNumStr, 10);
}

